LOAD spatial;

-- Snap each GPS ping to its closest point on the road.
-- Return: ping_id, snapped_x, snapped_y (rounded to 2dp) ordered by ping_id

setup:
CREATE TABLE road AS SELECT * FROM (VALUES
  (ST_GeomFromText('LINESTRING(0 0, 10 0)'))
) t(geom);

CREATE TABLE gps_pings AS SELECT * FROM (VALUES
  (1, ST_Point(3.0,  2.5)),
  (2, ST_Point(7.0, -1.8)),
  (3, ST_Point(11.0, 3.0))
) t(ping_id, geom);
